// Signing material is generated by scripts/setup-toolchain.ps1 into
// android/keystore.properties + android/keystore/dsbot.jks.
val keystorePropertiesFile: File = rootProject.file("keystore.properties")
val keystoreProperties = Properties().apply {
    if (keystorePropertiesFile.exists()) {
        keystorePropertiesFile.inputStream().use { load(it) }
    }
}
val hasKeystore = keystorePropertiesFile.exists()
val signingStoreFile: File? = keystoreProperties.getProperty("storeFile")?.let { rootProject.file(it) }

android {
    namespace = "com.dsbot.mobile"
    compileSdk = 35

    defaultConfig {
        applicationId = "com.dsbot.mobile"
        minSdk = 26
        targetSdk = 35
        versionCode = 1
        versionName = "0.1.0"
        vectorDrawables { useSupportLibrary = true }
    }

    signingConfigs {
        create("dsbot") {
            if (hasKeystore && signingStoreFile != null) {
                storeFile = signingStoreFile
                storePassword = keystoreProperties.getProperty("storePassword")
                keyAlias = keystoreProperties.getProperty("keyAlias")
                keyPassword = keystoreProperties.getProperty("keyPassword")
                storeType = keystoreProperties.getProperty("storeType", "PKCS12")
            }
        }
    }

    buildTypes {
        debug {
            if (hasKeystore) signingConfig = signingConfigs.getByName("dsbot")
        }
        release {
            isMinifyEnabled = false
